/**
 * @callback ForEachFunction
 * @param {number} i The index generated by the range function
 */

/**
 * @callback ForEachFunction2
 * @param {number} j The outer index generated by the range2 function
 * @param {number} i The inner index generated by the range2 function
 */

/**
 * The range function generates numbers from a start value to an end value (not
 * included) with an optional step. It helps replacing for loops by something
 * with a more functional approach.
 *
 * If the end value is not given, it will count from 0 to the start value (not
 * included).
 *
 * If end value is inferior to start value, it will count from start down to
 * end.
 *
 * A non-specified step is equivalent to 1.
 *
 * @param {number} start The start value
 * @param {number=} end The end value (not included)
 * @param {number=} step The optional step
 */
function* range(start, end, step) {
  if (start === undefined || start === end) return;

  if (end === undefined) {
    end = start;
    start = 0;
  }

  if (step === undefined) step = 1;

  step = Math.abs(step);

  if (end < start) {
    for (let i = start; i > end; i -= step) yield i;
  } else {
    for (let i = start; i < end; i += step) yield i;
  }
}

/**
 * The forEach method allows one to write loops like `range(100).forEach(func)`
 * where `func` is a function accepting one argument.
 *
 * @param {ForEachFunction} The function to be executed for each value generated
 *                          by the `range` function
 */
range().__proto__.forEach = function (func) {
  for (let i of this) func(i);
};

/**
 * The range2 function works like the range function but with 2 imbricated
 * generators. It helps replacing double for loops by something with a more
 * functional approach.
 *
 * @param {number[]} start The starting values
 * @param {number[]=} end The end values (not included)
 * @param {number[]=} step The optional steps
 */
function* range2(starts, ends, steps) {
  if (starts === undefined) return;

  if (ends === undefined) {
    ends = starts;
    starts = [0, 0];
  }

  if (steps === undefined) steps = [1, 1];

  const [jStart, iStart] = starts;
  const [jEnd, iEnd] = ends;
  const [jStep, iStep] = [
    Math.abs(steps[0]) * (jStart <= jEnd ? 1 : -1),
    Math.abs(steps[1]) * (iStart <= iEnd ? 1 : -1),
  ];

  if (jStart <= jEnd && iStart <= iEnd) {
    for (let j = jStart; j < jEnd; j += jStep) {
      for (let i = iStart; i < iEnd; i += iStep) {
        yield [j, i];
      }
    }
    return;
  }

  if (jStart <= jEnd && iStart > iEnd) {
    for (let j = jStart; j < jEnd; j += jStep) {
      for (let i = iStart; i > iEnd; i += iStep) {
        yield [j, i];
      }
    }
    return;
  }

  if (jStart > jEnd && iStart <= iEnd) {
    for (let j = jStart; j > jEnd; j += jStep) {
      for (let i = iStart; i < iEnd; i += iStep) {
        yield [j, i];
      }
    }
    return;
  }

  for (let j = jStart; j > jEnd; j += jStep) {
    for (let i = iStart; i > iEnd; i += iStep) {
      yield [j, i];
    }
  }
}

/**
 * The forEach method allows one to write loops like `range(5,10).forEach(func)`
 * where `func` is a function accepting one argument.
 *
 * @param {ForEachFunction2} The function to be executed for each value
 *                           generated by the `range2` function
 */
range2().__proto__.forEach = function (func) {
  for (let [j, i] of this) func(j, i);
};

/**
 * Autocallback is a method added to HTML DOM elements that allows you to
 * connect events occuring on elements to callback methods contained in an
 * object.
 *
 * Examples of attribute uses:
 *
 *     <form class="content-box" data-change="onChange">
 *         ...
 *     </form>
 *
 *     <button class="large" data-call="onCreateTidget" data-param="color-bg-3">
 *         <img src="icon/miicons.svg#color-bg-3" /><br/>Yellow<br/>90%
 *     </button>
 *
 * Examples of calls to the autocallback method:
 *
 *     this.ribbon.root.autocallback(this)
 *     container.find(".content-graphics")[0].autocallback(this)
 *     container.find(".drcs-black-white")[0].autocallback(this)
 *     container.find(".mosaic-exit")[0].autocallback(this)
 *
 * If the method indicated in the attribute does not exist in the object, it is
 * simply ignored.
 *
 * This methods looks for children elements having "data-call" and "data-change"
 * attributes.
 *
 * The child element may have a "data-param" attributes to pass specific
 * values to the callback.
 *
 * It works only on form (submit event), button (click event) and div (click
 * event) when using "data-call" attribute.
 *
 * When using "data-change" attribute on a form, every change occuring in the
 * form elements will fire the callback method.
 *
 * @param {} that The object containing the callback methods
 */
Element.prototype.autocallback = function (that) {
  const tagEvents = {
    form: "submit",
    button: "click",
    div: "click",
  };

  // Handles data-call attributes
  const dataCalls = [].slice.call(this.querySelectorAll("[data-call]"));

  dataCalls.map((element) => {
    // The specified handler must exist
    const handler = element.getAttribute("data-call");
    if (that[handler] === undefined) return;

    // Works only on supported tags
    const tagName = element.tagName.toLowerCase();
    if (tagEvents[tagName] === undefined) return;

    // Is there a parameter?
    let param = element.getAttribute("data-param");

    // Is it an object?
    if (param && param.startsWith("{")) param = JSON.parse(param);

    // Apply callback to the event
    element.addEventListener(tagEvents[tagName], (event) => {
      event.preventDefault();
      that[handler](event, param);
    });
  });

  // Handles data-change attributes
  const dataChanges = [].slice.call(this.querySelectorAll("[data-change]"));

  dataChanges.map((element) => {
    // The specified handler must exist
    const handler = element.getAttribute("data-change");
    if (that[handler] === undefined) return;

    // Is there a parameter?
    let param = element.getAttribute("data-param");

    // Is it an object?
    if (param && param.startsWith("{")) param = JSON.parse(param);

    // Apply callback to the event
    const formInputs = Array.prototype.slice.call(
      element.querySelectorAll("input, textarea, select")
    );

    formInputs.map((input) => {
      let eventType = "input";

      if (["radio", "checkbox", "select"].indexOf(input.localName) >= 0) {
        // Radio/check boxes/select do not fire "input" events
        eventType = "change";
      }

      input.addEventListener(eventType, (event) => {
        event.preventDefault();
        that[handler]({ target: element }, param);
      });
    });
  });
};

/**
 * @file finite-stack
 * @author Frédéric BISSON <zigazou@free.fr>
 * @version 1.0
 *
 * A finite stack is a stack that has a maximum number of elements. Pushing
 * elements when the stack is full just deletes the oldest values to make room
 * for the newest.
 *
 */

/**
 * @class FiniteStack
 */
class FiniteStack {
  /**
   * @param {number} maxLength Maximum length of our finite stack.
   */
  constructor(maxLength) {
    this.maxLength = maxLength;
    this.stack = [];
  }

  /**
   * @param value A value to push on the stack
   */
  push(value) {
    this.stack.push(value);
    if (this.stack.length > this.maxLength) {
      this.stack.shift();
    }
  }

  /**
   * Returns the last value pushed on the stack, null if the stack is empty.
   * This does not pop the value from the stack.
   */
  lastValue() {
    if (this.stack.length == 0) {
      return null;
    }

    return this.stack[this.stack.length - 1];
  }

  /**
   * Returns the last values pushed on the stack, [] if the stack is empty.
   * This does not pop the values from the stack. If the stack has less
   * elements than what is requested, it returns only theses elements.
   *
   * @param {number} count Number of values to return
   */
  lastValues(count) {
    return this.stack.slice(-count);
  }
}

/**
 * @file key-simulator
 * @author Frédéric BISSON <zigazou@free.fr>
 * @version 1.0
 *
 * This class aims to simulate keyboard click sounds.
 *
 */

/**
 * @class KeySimulator
 */
class KeySimulator {
  /**
   * @param {HTMLAudioElement} keyDownSound Sound when key is pressed.
   * @param {HTMLAudioElement} keyUpSound Sound when key is released.
   */
  constructor(keyDownSound, keyUpSound) {
    this.keyPressed = new Set();

    this.concurrentSound = 5;
    this.downStack = new Array(this.concurrentSound);
    this.upStack =
      keyUpSound === undefined ? undefined : new Array(this.concurrentSound);

    this.currentDownOffset = 0;
    this.currentUpOffset = 0;

    range(this.concurrentSound).forEach((i) => {
      this.downStack[i] = keyDownSound.cloneNode(true);
      if (this.upStack !== undefined) {
        this.upStack[i] = keyUpSound.cloneNode(true);
      }
    });
  }

  /**
   * Play the press sound
   */
  pressKey(keyCode) {
    if (this.upStack !== undefined) {
      if (this.keyPressed.has(keyCode)) return;
      this.keyPressed.add(keyCode);
    }

    this.downStack[this.currentDownOffset].currentTime = 0;
    this.downStack[this.currentDownOffset].play();

    this.currentDownOffset =
      (this.currentDownOffset + 1) % this.concurrentSound;
  }

  /**
   * Play the release sound
   */
  releaseKey(keyCode) {
    if (this.upStack === undefined) return;
    if (!this.keyPressed.has(keyCode)) return;

    this.keyPressed.delete(keyCode);

    this.upStack[this.currentDownOffset].currentTime = 0;
    this.upStack[this.currentDownOffset].play();

    this.currentUpOffset = (this.currentUpOffset + 1) % this.concurrentSound;
  }
}
